#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"


/* Array initialization.
 *
 * Optimizations:
 * - Use restrict-qualified local aliases to help the compiler assume
 *   non-aliasing and better vectorize.
 * - Replace repeated integer division by a single reciprocal
 *   (1.0 / m, 1.0 / n) followed by multiplications.
 * - Simplify (i % m) and (i % n) to i, since loop bounds guarantee
 *   0 <= i < m or n respectively.
 */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE *restrict r_ = r;
  DATA_TYPE *restrict p_ = p;

  const DATA_TYPE inv_m = SCALAR_VAL(1.0) / (DATA_TYPE)m;
  const DATA_TYPE inv_n = SCALAR_VAL(1.0) / (DATA_TYPE)n;

  /* p[i] = i / m */
  for (i = 0; i < m; i++)
    p_[i] = (DATA_TYPE)i * inv_m;

  for (i = 0; i < n; i++) {
    /* r[i] = i / n */
    r_[i] = (DATA_TYPE)i * inv_n;

    DATA_TYPE *restrict Ai = A_[i];

    for (j = 0; j < m; j++) {
      int v = (i * (j + 1)) % n;
      Ai[j] = (DATA_TYPE)v * inv_n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 * - Use restrict-qualified local aliases to aid vectorization and
 *   enable better alias analysis.
 * - Hoist loop-invariant loads (r[i] and A[i]) out of the inner j-loop.
 * - Accumulate q[i] in a scalar temporary and store once after the
 *   inner loop, reducing memory traffic.
 * - Use OpenMP parallelization on the outer i-loop with an array
 *   reduction on s[0:_PB_M]. This keeps the original fused usage of
 *   A[i][j] for both s and q while allowing safe parallel execution.
 *   If compiled without -fopenmp, the pragmas are ignored and the code
 *   executes sequentially with original semantics.
 */
static
void kernel_bicg [[gnu::flatten, gnu::noinline]] (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Create local restrict-qualified aliases.  These do not change the
   * observable behavior but let the compiler assume that A, s, q, p,
   * and r do not alias, which improves vectorization and scheduling.
   */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE *restrict s_ = s;
  DATA_TYPE *restrict q_ = q;
  DATA_TYPE *restrict p_ = p;
  DATA_TYPE *restrict r_ = r;

#pragma scop
  /* Initialize s to zero. This is kept separate from the main
   * parallel loop for clarity; it's cheap compared to the kernel.
   */
  for (i = 0; i < _PB_M; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* Outer loop over rows of A. We parallelize this loop when compiled
   * with OpenMP. The s_ array is treated as a reduction variable so
   * each thread accumulates a private copy and the partial sums are
   * combined at the end. This preserves the mathematical result of:
   *
   *   s[j] = sum_i r[i] * A[i][j];
   *   q[i] = sum_j A[i][j] * p[j];
   *
   * while allowing concurrent execution of different i-iterations.
   */
#pragma omp parallel for schedule(static) reduction(+:s_[0:_PB_M])
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE qi = SCALAR_VAL(0.0);   /* local accumulator for q[i] */
      DATA_TYPE ri = r_[i];             /* hoisted load of r[i] */
      DATA_TYPE *restrict Ai = A_[i];   /* pointer to row A[i][0..m-1] */

      for (j = 0; j < _PB_M; j++)
	{
	  DATA_TYPE Aij = Ai[j];
	  s_[j] += ri * Aij;
	  qi    += Aij * p_[j];
	}

      q_[i] = qi;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
