  /* Fused BiCG kernel.
     For each row i:
       - update s[j] with r[i] * A[i][j]  (BiCG A^T * r part)
       - compute q[i] = sum_j A[i][j] * p[j]  (BiCG A * p part)

     The loop nest is kept fused so that each A[i][j] element is loaded
     from memory only once and reused for both computations.  A scalar
     accumulator q_i avoids repeated loads/stores of q[i] in the inner
     loop, reducing memory traffic and exposing a simple reduction
     pattern for vectorization. */
  for (i = 0; i < _PB_N; i++)
    {
      const DATA_TYPE r_i = r_[i];
      const DATA_TYPE *restrict Ai = A_[i];
      DATA_TYPE q_i = SCALAR_VAL(0.0);

#pragma GCC ivdep  /* Assert no loop-carried dependencies w.r.t. j. */
      for (j = 0; j < _PB_M; j++)
        {
          const DATA_TYPE A_ij = Ai[j];

          /* Update s and accumulate q_i.  The order of operations for
             both reductions (over i for s[j] and over j for q[i]) is
             preserved with respect to the original code. */
          s_[j] += r_i * A_ij;
          q_i   += A_ij * p_[j];
        }

      /* Single store of q[i] after the inner reduction completes. */
      q_[i] = q_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}

