/* Array initialization.
 *
 * Optimizations:
 *  - Use restrict-qualified local pointers to help alias analysis.
 *  - Remove mathematically redundant mod operations in p and r
 *    initializations (since loop bounds guarantee 0 <= i < m or n).
 *  - Keep initialization order (row-major for A) to preserve good
 *    spatial locality.
 */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  /* Help the compiler with alias analysis.  In the function
     signature, the arrays have been adjusted to pointers by the
     C language rules; here we add restrict-qualified aliases and use
     them exclusively below. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE *restrict r_ = r;
  DATA_TYPE *restrict p_ = p;

  /* Initialize p.  Original code used (i % m) / m, but since the loop
     bound is i < m, (i % m) == i holds and we can drop the modulo. */
  for (i = 0; i < m; i++)
    p_[i] = (DATA_TYPE)i / m;

  /* Initialize r and A.  We keep the same mathematical definition for A. */
  for (i = 0; i < n; i++) {
    DATA_TYPE ri = (DATA_TYPE)i / n; /* (i % n) / n == i / n for i < n */
    r_[i] = ri;

    for (j = 0; j < m; j++)
      A_[i][j] = (DATA_TYPE)((i * (j + 1)) % n) / n;
  }
}


