}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original mathematical specification:
 *   s[j] = sum_i r[i] * A[i][j]
 *   q[i] = sum_j A[i][j] * p[j]
 *
 * Optimizations:
 *  - Introduce restrict-qualified local aliases for all arrays to
 *    improve alias analysis and enable better vectorization.
 *  - Keep the fused use of A to maintain good cache locality
 *    (each A[i][j] is used once for s and once for q).
 *  - Parallelize over i (rows of A) with OpenMP and use an OpenMP
 *    array reduction for s to safely accumulate contributions from
 *    all threads without data races:
 *        s[j] = sum_i r[i] * A[i][j]
 *    This is mathematically equivalent to the sequential version.
 *  - Use 'omp simd' on the inner loop to encourage vectorization.
 *  - All OpenMP directives are optional: when compiled without
 *    -fopenmp they are ignored as comments, preserving sequential
 *    semantics unchanged.
 */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Local restrict-qualified aliases for better optimization. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE *restrict s_ = s;
  DATA_TYPE *restrict q_ = q;
  DATA_TYPE *restrict p_ = p;
  DATA_TYPE *restrict r_ = r;

#pragma scop
  /* Initialize s to zero.  q is fully overwritten in the main loop. */
  for (i = 0; i < _PB_M; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* Parallel over rows of A.  Each iteration computes q[i] and
     contributes to all s[j].  The contribution to s is expressed
     as an OpenMP array reduction, which is equivalent to:
         s[j] = sum_i r[i] * A[i][j]
     but allows safe parallel execution. */
#pragma omp parallel for schedule(static) reduction(+:s_[:_PB_M]) private(j) \
    if (_PB_N * _PB_M > 1024)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE r_i = r_[i];
      DATA_TYPE q_i = SCALAR_VAL(0.0);

      /* Inner loop: contiguous access along row i of A and
         corresponding elements of p and s.
         'omp simd' encourages vectorization across j. */
#pragma omp simd
      for (j = 0; j < _PB_M; j++)
	{
	  DATA_TYPE a_ij = A_[i][j];
	  s_[j] += r_i * a_ij;
	  q_i   += a_ij * p_[j];
	}

      q_[i] = q_i;
    }
#pragma endscop

}


